function get_category_table_body($categories) {
    $no = 0;
    $html = '';
    foreach($categories as $category)
    {
        $html .= '<tr>
            <td>'. ++$no .'</td>
            <td>'.$category->name.'</td>
            <td>'.$category->branches.'</td>
            <td>
                '.$category->total;
                if($category->total > 0) {
                    $html .= '<a id="'.$category->id.'" data-original-title="view" data-toggle="tooltip" data-placement="top" class="btnaction btn menu-icon vd_bd-green vd_green total_devices"> <i class="bi bi-eye-fill"></i> </a>';
                }
            $html .= '</td>
            <td>
                '.$category->available;
                if($category->available > 0) {
                    $html .= '<a id="'.$category->id.'" data-original-title="view" data-toggle="tooltip" data-placement="top" class="btnaction btn menu-icon vd_bd-green vd_green available_devices"> <i class="bi bi-eye-fill"></i> </a>';
                }
            $html .= '</td>
        </tr>';
    }
    return $html;
}
function get_device_table_body($devices) {
    $no = 0;
    $html = '';
    foreach($devices as $device)
    {
        $html .= '<tr>
            <td>'.++$no.'</td>
            <td><center>
                '.$device->user_name.'<br><br>
                <a id="'.$device->user_id.'" data-original-title="view" data-toggle="tooltip" data-placement="top" class="btnaction btn menu-icon vd_bd-green vd_green view"> <i class="bi bi-eye-fill"></i> </a></center>
            </td>
            <td>'.$device->branches.'</td>
            <td>#'.strtoupper($device->reference_no).'</td>
            <td>'.$device->device_names.'</td>
            <td>'.$device->assigned_by.'</td>
            <td>'.$device->assign_at.'</td>
            <td style="text-align: center">';
            if($device->delivery_timestamp != '')
                $status = '<span class="label label-success">Assignment Done</span>';
            else if($device->admin_approval_by > 0)
                $status = 'Awaiting <span style="color: #FF9800;">'.$device->user_name.'</span> Signature';
            else
                $status = 'Awaiting <span style="color: #FF9800;">'.$device->assign_by.'</span> Approvel';
            $html .= $status .'
            </td>
            <td>
                '.$device->action.'
            </td>
        </tr>';
    }
    return $html;
}
class PropertyIssuanceController extends Controller
{

    public function __construct()
    {
        $this->middleware('auth')->except(['CompanyProprtiesIssuance', 'propertiesConfirm']);
    }
    public function get_total_devices($id) {
        $data = DB::select("SELECT * FROM btc_properties WHERE property_id='$id'");
        return view('new_porttal.PropertyIssuance.devices')->with('devices', $data);
    }
    public function get_available_devices($id) {
        $data = DB::select("SELECT * FROM btc_properties WHERE property_id='$id' AND status_id = 1");
        return view('new_porttal.PropertyIssuance.devices')->with('devices', $data);
    }
    public function propertiesConfirm($token){
         DB::update("UPDATE `properties_assignment` SET `delivery_timestamp`=NOW() WHERE `reference_no`='".$token."'");
        //  dd($payload);
        // send a confirmation email to created by or/and HR
        $data = DB::select("SELECT users.NAME,assigned_user.NAME AS to_user,users.email FROM properties_assignment INNER JOIN users ON properties_assignment.assign_by=users.id INNER JOIN users assigned_user ON properties_assignment.user_id=assigned_user.id WHERE reference_no='$token'");
        $name = $data[0]->to_user;
        $email = $data[0]->email;
        $btn = '<p><img src="data:image/png;base64," style="height:38px; width:100px" /></p>';
        $msg = "Dear HR,<br><br> We would like to inform you that the employee <b>$name</b> Has signed the property assurance (#".strtoupper($token)."). <br> You can check it by clicking on the like bellow .
        <a href='https://btcdmins.com/Properties/index'>$btn</a>
        <br><br>Best Regards. <br>System generated Email.";
        $hr = "cpm@btclogistic.com";
        if($email == $hr)
            $hr = "";
        $recipients = [
            $email,
            // 'm.shehroze@btclogistic.com',
        ];
        $ccRecipients = [
            $hr,
        ];
        $subject = "E-Signature done";
        $email_status = HelperFunctionsController::send_email($recipients, $ccRecipients, $msg, $subject);
        if($email_status == false) {
            return response()->json(['message' => 'Failed to send email.'], 500);
        } else {
            return redirect()->back()->with('success', 'Approved successful');
        }
        return "propertiesConfirm";
    }
    public function CompanyProprtiesIssuance($user_id, $type){
        // dd($user_id);
        // $filename = 'hello_world.pdf';
        $sql = "SELECT users.name as 'user_name',users.department,users.IdentityNo,btc_properties.*,lkp_properties_category.name_ar as 'category_name_ar',lkp_properties_status.status_ar,`properties_assignment`.reference_no,`properties_assignment`.delivery_timestamp FROM `properties_assignment` JOIN users ON users.id = properties_assignment.user_id JOIN btc_properties ON btc_properties.id = properties_assignment.property_id JOIN lkp_properties_category ON lkp_properties_category.id = btc_properties.property_id JOIN lkp_properties_status ON lkp_properties_status.id = btc_properties.status_id WHERE properties_assignment.reference_no = '".$user_id."';"; //2
        $payload = DB::select($sql);
        // dd($payload[0]->category_name_ar);
        $table = array();
        foreach($payload as $getuniq){
            // dd($getuniq->category_name_ar);
            $uniq_array[] = $getuniq->name.' ('.$getuniq->category_name_ar.') - '.$getuniq->description ;
        }
        $uniq_arrayssss = array_unique($uniq_array);
        $uniq_array = array_count_values($uniq_array);
        foreach($uniq_arrayssss as $item){
            $table[] = [
                "description"=>$item,
                "status"=>$getuniq->status_ar,
                "qty"=>$uniq_array[$item]
            ];
        }
        // dd($payload);
        return view('new_porttal.CompanyProprtiesIssuanceForm',compact('payload','table', 'type'));
        // return response()->download(public_path($filename));

        // return view('CompanyProprtiesIssuanceForm');
    }
    public function get_back_devices(Request $request)
    {
        $user_id = $request->user_id;
        $devices = DB::select("SELECT btc_properties.`id`,btc_properties.`name`,btc_properties.description,users.`id` as user_id,users.`name` as user_name FROM btc_properties INNER JOIN properties_assignment ON btc_properties.id=properties_assignment.property_id INNER JOIN users ON properties_assignment.user_id=users.id WHERE properties_assignment.reference_no='$user_id'");
        return view('new_porttal.PropertyIssuance.get_devices')->with('devices', $devices);

    }
    public function get_devices_back(Request $request)
    {
        $user_id = Auth::user()->id;
        $devices = $request->devices;
        if($devices != null) {
            foreach($devices as $device) {
                DB::update("UPDATE btc_properties set status_id = '1', updated_by = '$user_id', updated_at = NOW() WHERE id = '$device'");
                DB::delete("DELETE from properties_assignment WHERE property_id = '$device'");
            }
            return redirect()->back()->with('success', "Data Updated successfully");
        } else
            return redirect()->back()->with('error', "You did not select any device.");
    }
    public function index_new(Request $request)
    {
        $employees = DB::select("SELECT id, name from users");
        $assign_employees = DB::select("SELECT users.id,users.`name` FROM properties_assignment INNER JOIN users ON properties_assignment.user_id=users.id GROUP BY users.id,users.`name` ORDER BY users.`name`");
        $branches = DB::select("SELECT distinct branches from btc_properties");

        // devices section start
        $categories = DB::select("SELECT * from lkp_properties_category");
        foreach($categories as $row) {
            $id = $row->id;
            $items = DB::select("SELECT * from btc_properties Where property_id = '$id'");
            $row->total = count($items);
            $items = DB::select("SELECT * from btc_properties Where property_id = '$id' AND status_id = 1");
            $row->available = count($items);
            $items = DB::select("SELECT distinct branches from btc_properties Where property_id = '$id'");
            $html = '<ul>';
            foreach($items as $item) {
                $html .= '<li>'.$item->branches.'</li>';
            }
            $html .= '</ul>';
            $row->branches = $html;
        }
        // devices section end
        // property issuance section start
        $devices = DB::select("SELECT users.`id` AS user_id, users.`name` AS user_name,properties_assignment.assign_by as assigned_by,properties_assignment.assign_at,properties_assignment.reference_no,properties_assignment.admin_approval_by,properties_assignment.delivery_timestamp,GROUP_CONCAT(DISTINCT btc_properties.`name` ORDER BY btc_properties.`name` ASC) AS device_names, btc_properties.id,btc_properties.branches FROM properties_assignment INNER JOIN users ON properties_assignment.user_id=users.id INNER JOIN btc_properties ON properties_assignment.property_id=btc_properties.id GROUP BY users.id,properties_assignment.reference_no,btc_properties.branches order by properties_assignment.id desc");

        foreach($devices as $device) {
            $device_names = explode(',', $device->device_names);
            $user_id = $device->user_id;
            $reference_no = $device->reference_no;
            $html = '<ul>';
            $count = 0;
            foreach($device_names as $name) {
                $cont = DB::select("SELECT users.`name` as assign_by, btc_properties.name, btc_properties.description FROM btc_properties INNER JOIN properties_assignment ON btc_properties.id=properties_assignment.property_id INNER JOIN users ON properties_assignment.assign_by = users.id WHERE properties_assignment.reference_no='$reference_no' AND properties_assignment.user_id='$user_id' AND btc_properties.`name`='$name'");

                $count = count($cont);

                if($count>0){
                    $html .= "<li>".$cont[0]->name." (".$cont[0]->description.") <span style='color: red; font-size: 14px'>*</span> <b style='color: #d7d322; font-size: 14px'>(".$count.")</b></li>";
                    $assign_by = $cont[0]->assign_by;
                }else{
                    $assign_by = null;
                }

            }
            $html .= '</ul>';
            $device->device_names = $html;
            // dd($device);
            $device->device_names .= "<center><a href='/Properties/Form/".$device->reference_no."/view' target='_blank' data-original-title='view' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-green vd_green'> <i class='bi bi-eye-fill'></i> </a></center>";
            $device->assign_by = $assign_by;
            $device->action = "<center>";
            if($device->admin_approval_by == '')
                $device->action .= "<a onclick='devices_confirmation(`".$device->reference_no."`)' data-original-title='confirm device(s) list' title='confirm device(s) list' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-green vd_green'> <i class='bi bi-check-square-fill'></i> </a>";

            $device->action .= "<a href='#' onclick='get_devices(`".$device->reference_no."`)' data-original-title='receive device(s)' title='receive device(s)' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-yellow vd_yellow'> <i class='bi bi-arrow-counterclockwise'></i> </a>";
            if($device->admin_approval_by == '')
                $device->action .= "<a onclick=\"delete_record($device->id, 'pro')\" href='#' data-original-title='delete' title='delete' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-red vd_red' aria-describedby='tooltip944117'> <i class='bi bi-trash-fill'></i> </a>";
            $device->action .= "</center>";

            $assigned_by = $device->assigned_by;
            $assigned = DB::select("SELECT users.`name` from users where id = '$assigned_by'");
            if(count($assigned)>0){
                $device->assigned_by = $assigned[0]->name;
            }


        }

        if(count($branches)>5){
            $swap=$branches[5];
            $branches[5] = $branches[3];
            $branches[3] = $swap;
        }
        return view('new_porttal.PropertyIssuance.index')->with('assign_employees', $assign_employees)->with('categories', $categories)->with('employees', $employees)->with('branches', $branches)->with('devices', $devices);
    }
    public function search(Request $request)
    {
        $filter_referenceId = $request->filter_referenceId;
        $filter_deviceType = $request->filter_deviceType;
        $filter_deliveryApprove = $request->filter_deliveryApprove;
        $filter_createdBy = $request->filter_createdBy;
        $filter_emp = $request->filter_emp;
        $filter_branch = $request->filter_branch;
        $filter_status = $request->filter_status;
        $clause_status = $clause_branch = $clause_emp = $clause_createdBy = $clause_deliveryApprove = $clause_referenceId = $clause_deviceType = "";
        if($filter_deviceType != '') {
            $clause_deviceType = " AND lkp_properties_category.id = '$filter_deviceType'";
        }
        if($filter_referenceId != '') {
            $clause_referenceId = " AND properties_assignment.reference_no = '$filter_referenceId'";
        }
        if($filter_deliveryApprove != '') {
            $clause_deliveryApprove = " AND properties_assignment.delivery_timestamp is null";
            if($filter_deliveryApprove == 1)
                $clause_deliveryApprove = " AND properties_assignment.delivery_timestamp is not null";
        }
        if($filter_createdBy != '') {
            $clause_createdBy = " AND properties_assignment.assign_by = '$filter_createdBy'";
        }
        if($filter_emp != '') {
            $clause_emp = " AND properties_assignment.user_id = '$filter_emp'";
        }
        if($filter_branch != '') {
            $clause_branch = " AND btc_properties.branches = '$filter_branch'";
        }
        if($filter_status != '') {
            $clause_status = " AND btc_properties.status_id = '$filter_status'";
        }


        // devices section start
        $categories = DB::select("SELECT * from lkp_properties_category WHERE 1 = 1 $clause_deviceType");
        foreach($categories as $row) {
            $id = $row->id;
            $items = DB::select("SELECT * from btc_properties Where property_id = '$id'");
            $row->total = count($items);
            $items = DB::select("SELECT * from btc_properties Where property_id = '$id' AND status_id = 1");
            $row->available = count($items);
            $items = DB::select("SELECT distinct branches from btc_properties Where property_id = '$id'");
            $html = '<ul>';
            foreach($items as $item) {
                $html .= '<li>'.$item->branches.'</li>';
            }
            $html .= '</ul>';
            $row->branches = $html;
        }
        // devices section end
        // property issuance section start
        $devices = DB::select("SELECT users.`id` AS user_id, users.`name` AS user_name,properties_assignment.assign_by as assigned_by,properties_assignment.assign_at,properties_assignment.reference_no,properties_assignment.admin_approval_by,properties_assignment.delivery_timestamp,GROUP_CONCAT(DISTINCT btc_properties.`name` ORDER BY btc_properties.`name` ASC) AS device_names, btc_properties.id,btc_properties.branches FROM properties_assignment INNER JOIN users ON properties_assignment.user_id=users.id INNER JOIN btc_properties ON properties_assignment.property_id=btc_properties.id INNER JOIN lkp_properties_category ON btc_properties.property_id = lkp_properties_category.id WHERE 1 = 1 $clause_deviceType $clause_referenceId $clause_deliveryApprove $clause_createdBy $clause_emp $clause_branch $clause_status GROUP BY users.id,properties_assignment.reference_no,btc_properties.branches");
        foreach($devices as $device) {
            $device_names = explode(',', $device->device_names);
            $user_id = $device->user_id;
            $html = '<ul>';
            foreach($device_names as $name) {
                $cont = DB::select("SELECT users.`name` as assign_by, btc_properties.name, btc_properties.description FROM btc_properties INNER JOIN properties_assignment ON btc_properties.id=properties_assignment.property_id INNER JOIN users ON properties_assignment.assign_by = users.id WHERE properties_assignment.user_id='$user_id' AND btc_properties.`name`='$name'");
                $count = count($cont);
                $html .= "<li>".$cont[0]->name." (".$cont[0]->description.") <span style='color: red; font-size: 14px'>*</span> <b style='color: #d7d322; font-size: 14px'>(".$count.")</b></li>";
                $assign_by = $cont[0]->assign_by;
            }
            $html .= '</ul>';
            $device->device_names = $html;
            // dd($device);
            $device->device_names .= "<center><a href='/Properties/Form/".$device->reference_no."/view' target='_blank' data-original-title='view' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-green vd_green'> <i class='bi bi-eye-fill'></i> </a></center>";
            $device->assign_by = $assign_by;
            $device->action = "<center>";
            if($device->admin_approval_by == '') {
                $device->action .= "<a onclick='devices_confirmation(`".$device->reference_no."`)' data-original-title='confirm device(s) list' title='confirm device(s) list' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-green vd_green'> <i class='bi bi-check-square-fill'></i> </a>";
            }
            $device->action .= "<a href='#' onclick='get_devices(`".$device->reference_no."`)' data-original-title='receive device(s)' title='receive device(s)' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-yellow vd_yellow'> <i class='bi bi-arrow-counterclockwise'></i> </a>";
            if($device->admin_approval_by == '') {
                $device->action .= "<a onclick=\"delete_record($device->id, 'pro')\" href='#' data-original-title='delete' title='delete' data-toggle='tooltip' data-placement='top' class='btnaction btn menu-icon vd_bd-red vd_red' aria-describedby='tooltip944117'> <i class='bi bi-trash-fill'></i> </a>";
            }
            $device->action .= "</center>";
            $assigned_by = $device->assigned_by;
            $assigned = DB::select("SELECT users.`name` from users where id = '$assigned_by'");
            $device->assigned_by = $assigned[0]->name;
        }
        echo get_category_table_body($categories);
        echo ':::';
        echo get_device_table_body($devices);
    }
    public function index(Request $request)
    {
        $categories = DB::select("SELECT * from lkp_properties_category");
        foreach($categories as $row) {
            $id = $row->id;
            $items = DB::select("SELECT * from btc_properties Where property_id = '$id'");
            $row->quantity = count($items);
            $html = '<ul>';
            foreach($items as $item) {
                $user_name = '';
                if($item->status_id == 2) {
                    $property_id = $item->id;
                    $user = DB::select("select properties_assignment.id, users.name as user_name from properties_assignment join users on properties_assignment.user_id = users.id WHERE property_id = '$property_id' ORDER BY properties_assignment.id DESC");
                    $user_name = $user[0]->user_name;
                }
                if ($user_name == '')
                    $html .= '<li>'.$item->name.'</li>';
                else
                    $html .= '<li>'.$item->name.' ('.$user_name.')</li>';
            }
            $html .= '</ul>';
            $row->items = $html;
        }

        return view('new_porttal.PropertyIssuance.index')->with('categories', $categories);
    }
    public function index_assign(Request $request)
    {
        $user_id = Auth::user()->id;
        $properties = DB::select("SELECT btc_properties.*, lkp_properties_category.name as cat_name, lkp_properties_status.status FROM btc_properties INNER JOIN lkp_properties_category ON btc_properties.property_id=lkp_properties_category.id INNER JOIN lkp_properties_status ON btc_properties.status_id=lkp_properties_status.id order by lkp_properties_category.id");
        foreach($properties as $property) {
            if($property->status_id == 2) {
                $property_id = $property->id;
                $user = DB::select("select properties_assignment.id, users.name as user_name from properties_assignment join users on properties_assignment.user_id = users.id WHERE property_id = '$property_id' ORDER BY properties_assignment.id DESC");
                $property->user_name = $user[0]->user_name;
            } else {
                $property->user_name = '';
            }
        }
        $allCategories = DB::select("SELECT * from lkp_properties_category");
        $categoryTotal = $categoryAvaiable = $categories = array();

        foreach($allCategories as $row) {
            $id = $row->id;
            $categories[] = "'" .$row->name. "'";
            $pro = DB::select("SELECT * from btc_properties Where status_id = '1' AND property_id = '$id'");
            $categoryAvaiable[] = count($pro);
            $pro = DB::select("SELECT * from btc_properties Where property_id = '$id'");
            $categoryTotal[] = count($pro);
        }

        return view('new_porttal.PropertyIssuance.index_issue')->with('properties', $properties)->with('categories', $categories)->with('categoryAvaiable', $categoryAvaiable)->with('categoryTotal', $categoryTotal);
    }
    public function devices_confirmation(Request $request)
    {
        $reference_no = $request->reference_no;
        $devices = DB::select("SELECT properties_assignment.reference_no, btc_properties.`id`,btc_properties.`name`,btc_properties.description,users.`id` as user_id,users.`name` as user_name FROM btc_properties INNER JOIN properties_assignment ON btc_properties.id=properties_assignment.property_id INNER JOIN users ON properties_assignment.user_id=users.id WHERE reference_no='$reference_no'");
        return view('new_porttal.PropertyIssuance.confirm_devices')->with('devices', $devices);
    }
    public function confirm_devices_for_emp(Request $request)
    {
        $user_id = Auth::user()->id;
        $reference_no = $request->reference_no;
        if($request->check == '1') {
            DB::update("UPDATE properties_assignment set admin_approval_by = '$user_id', admin_approval_stamp = NOW() WHERE reference_no = '$reference_no'");
            $data = DB::select("SELECT users.`name`,users.email FROM properties_assignment INNER JOIN users ON properties_assignment.user_id=users.id WHERE reference_no = '$reference_no'");
            $name = $data[0]->name;
            $email = $data[0]->email;
            $btn = '<p><img src="data:image/png;base64," style="height:38px; width:100px" /></p>';
            $msg = "Dear $name,<br> <br> Kindly check & review the propriety insurance (#".strtoupper($request->reference_no).") from the link below:
                <a href='https://btcdmins.com/Properties/Form/$reference_no/check'>$btn</a> <br> Best Regards.  <br>System generated Email. ";
            $recipients = [
                    $email,
                    // 'muhammad.shehroze@spsnet.com'
                    // 'm.shehroze@btclogistic.com',
                ];
                $ccRecipients = [
                    // 'cpm@btclogistic.com',
                ];
                $subject = "E-Signature for Device(s) recieving";
                $email_status = HelperFunctionsController::send_email($recipients, $ccRecipients, $msg, $subject);
                if($email_status == false) {
                    return response()->json(['message' => 'Failed to send email.'], 500);
                } else {
                    return redirect()->back()->with('success', 'Approved successful');
                }
        } else {
            return redirect()->back()->with('error', 'Please select the checkbox.');
        }
    }



    public function create(Request $request)
    {
        $type = $request->type;
        if($type == 'assign') {
            $categories = DB::select('SELECT * from lkp_properties_category');
            $users = DB::select('SELECT * from users where active_id = 1');
            $properties = DB::select("SELECT * from btc_properties where status_id = '1'");


            $branches = DB::select("SELECT DISTINCT description, branches FROM btc_properties WHERE status_id = 1 ORDER BY name");
            foreach($branches as $branch) {
                $cont = DB::select("SELECT name FROM btc_properties WHERE status_id = 1 AND description = '". $branch->description. "' AND branches = '". $branch->branches."'");
                $branch->device = $cont[0]->name;
                $branch->available = count($cont);
            }

            return view('new_porttal.PropertyIssuance.assign')->with('branches', $branches)->with('properties', $properties)->with('categories', $categories)->with('users', $users);

        } else if($type == 'cat') {
            $categories = DB::select('SELECT lkp_properties_category.*, users.`name` as user_name from lkp_properties_category join users on lkp_properties_category.created_by = users.id');
            return view('new_porttal.PropertyIssuance.create')->with('categories', $categories)->with('type', $type);
        } else {
            $categories = DB::select('SELECT * from lkp_properties_category');
            $status = DB::select('SELECT * from lkp_properties_status');
            $branches = DB::select("SELECT DISTINCT branches FROM btc_properties ORDER BY name");
            return view('new_porttal.PropertyIssuance.create')->with('branches', $branches)->with('categories', $categories)->with('type', $type)->with('status', $status);
        }
    }
    public function store(Request $request)
    {
        $type = $request->type;
        $name = $request->name;
        $id = $request->cat_id;
        $user_id = Auth::user()->id;
        if($type == 'cat') {
            if($id > 0)
                DB::update("UPDATE lkp_properties_category set name = '$name', updated_by = '$user_id', updated_at = NOW() WHERE id = '$id'");
            else
                DB::insert("INSERT into lkp_properties_category (name, created_by, created_at) VALUES ('$name', '$user_id', NOW())");
        } else {
            $property_id = $request->property_id;
            $description = $request->description;
            $price = $request->price;
            $status_id = $request->status_id;
            $branches = $request->branches;
            if($branches == 'other')
                $branches = $request->new_branches;

            DB::insert("INSERT into btc_properties (property_id, name, description, price, status_id, branches, created_by, created_at) VALUES ('$property_id', '$name', '$description', '$price', '$status_id', '$branches', '$user_id', NOW())");
        }
        return redirect('New-Portal/Properties/index')->with('success', "Data Added successfully");
    }
    public function get(Request $request)
    {
        $type = $request->type;
        $id = $request->id;
        $property = DB::select("SELECT btc_properties.*, lkp_properties_category.name as cat_name, lkp_properties_status.status FROM btc_properties INNER JOIN lkp_properties_category ON btc_properties.property_id=lkp_properties_category.id INNER JOIN lkp_properties_status ON btc_properties.status_id=lkp_properties_status.id WHERE btc_properties.id = '$id'");
        $categories = DB::select('SELECT * from lkp_properties_category');
        $status = DB::select('SELECT * from lkp_properties_status');
        $branches = DB::select("SELECT DISTINCT branches FROM btc_properties ORDER BY name");
        return view('new_porttal.PropertyIssuance.edit')->with('branches', $branches)->with('categories', $categories)->with('type', $type)->with('status', $status)->with('property', $property);
    }

    public function update(Request $request)
    {
        $user_id = Auth::user()->id;
        $type = $request->type;
        $name = $request->name;
        $id = $request->id;
        $property_id = $request->property_id;
        $description = $request->description;
        $price = $request->price;
        $status_id = $request->status_id;
        DB::update("UPDATE btc_properties set property_id = '$property_id', name = '$name', description = '$description', price = '$price', status_id = '$status_id', updated_by = '$user_id', updated_at = NOW() WHERE id = '$id'");
        return redirect('New-Portal/Properties/index')->with('success', "Data Updated successfully");
    }
    public function delete($id)
    {
        DB::delete("DELETE FROM btc_properties WHERE id = '$id'");
        DB::delete("DELETE FROM properties_assignment WHERE property_id = '$id'");
        return redirect('New-Portal/Properties/index')->with('success', "Data DELETED successfully");
    }
    public function cat_delete($id)
    {
        DB::delete("DELETE FROM lkp_properties_category WHERE id = '$id'");
        $properties = DB::select("SELECT * from btc_properties where property_id = '$id'");
        foreach($properties as $property) {
            DB::delete("DELETE FROM properties_assignment WHERE property_id = '$property'");
        }
        DB::delete("DELETE FROM btc_properties WHERE property_id = '$id'");
        return redirect('New-Portal/Properties/index')->with('success', "Data DELETED successfully");
    }
