    public function property_assign(Request $request)
    {
        $user_id = Auth::user()->id;
        $emp_id = $request->emp_id;
        $properties = $request->properties;
        $descriptions = $request->descriptions;
        $branches = $request->branches;
        $reference_no = Str::random(8);
        // $ref = DB::select("SELECT reference_no FROM properties_assignment WHERE user_id = $emp_id");
        // if(count($ref) > 0) {
        //     $reference_no = $ref[0]->reference_no;
        // }
        $j = 0;
        foreach($descriptions as $description) {
            $i = 0;
            $branch = $branches[$j];

            if($properties[$j] > 0 AND $properties[$j] != '') {
                // echo $properties[$j];
                $devices = DB::select("SELECT * FROM btc_properties WHERE status_id = 1 AND branches = '$branch' AND description = '$description'");
                foreach($devices as $device) {
                    if($i < $properties[$j]) {
                        $device_id = $device->id;
                        DB::update("UPDATE btc_properties set status_id = '2', updated_by = '$user_id', updated_at = NOW() WHERE id = '$device_id'");
                        DB::insert("INSERT into properties_assignment (reference_no, user_id, property_id, assign_by, assign_at) VALUES ('$reference_no', '$emp_id', '$device_id', '$user_id', NOW())");
                    }
                    $i++;
                }
            }
            $j++;
        }
        return redirect()->back()->with('success', "Data Updated successfully");

